(async () => {
                        // 0. Active Hydration Wait: Wait until either React Fiber orders exist OR DOM tbody tr > 5
                        const t0 = Date.now();
                        let rawOrders = [];
                        while (Date.now() - t0 < 9000) {
                            const container = document.querySelector('.lo-bt-body');
                            if (container) {
                                const key = Object.keys(container).find(k => k.startsWith('__reactFiber$'));
                                let fiber = container[key];
                                while (fiber) {
                                    let st = fiber.memoizedState;
                                    while (st) {
                                        const val = st.memoizedState;
                                        if (val && typeof val === 'object' && Array.isArray(val['0']) && val['0'].length > 0) {
                                            if (val['0'][0] && (val['0'][0].usd !== undefined || val['0'][0].initUsd !== undefined)) {
                                                rawOrders = val['0'];
                                                break;
                                            }
                                        }
                                        st = st.next;
                                    }
                                    if (rawOrders.length > 0) break;
                                    fiber = fiber.return;
                                }
                            }
                            if (rawOrders.length > 5 || document.querySelectorAll('.lo-bt-body table tbody tr').length > 5) break;
                            await new Promise(r => setTimeout(r, 250));
                        }

                        // 1. Ensure Size threshold is strictly $0 (no limit - captures all orders)
                        const rail = document.querySelector('.lo-rail') || document.body;
                        const selects = Array.from(rail.querySelectorAll('[class*="ui_select"], [class*="select"]'));
                        const thrSelect = selects.find(el => el.innerText && (el.innerText.includes('Size threshold') || el.innerText.includes('≥$')));

                        if (thrSelect && !thrSelect.innerText.includes('$0')) {
                            ['pointerdown', 'mousedown', 'pointerup', 'mouseup', 'click'].forEach(evt =>
                                thrSelect.dispatchEvent(new MouseEvent(evt, {bubbles: true, cancelable: true}))
                            );
                            await new Promise(r => setTimeout(r, 400));
                            const pop = Array.from(document.body.children).find(c => c.tagName === 'DIV' && c.id !== '__next' && (c.innerText.includes('$0') || c.innerText.includes('≥$')));
                            if (pop) {
                                const zeroItem = Array.from(pop.querySelectorAll('*')).find(e => e.children.length === 0 && e.innerText && e.innerText.trim() === '$0');
                                if (zeroItem) {
                                    zeroItem.click();
                                    await new Promise(r => setTimeout(r, 1000));
                                }
                            }
                        }

                        const exMap = {
                            'cb-spot': 'Coinbase Spot', 'bn-spot': 'Binance Spot', 'bn-perp': 'Binance Perp',
                            'hl-perp': 'Hyperliquid Perp', 'bybit-spot': 'Bybit Spot', 'bybit-perp': 'Bybit Perp',
                            'okx-perp': 'OKX Perp', 'okx-spot': 'OKX Spot', 'bitget-perp': 'Bitget Perp',
                            'gate-perp': 'Gate Perp', 'kraken-spot': 'Kraken Spot'
                        };

                        function formatUsd(v) {
                            if (!v || v === 0) return '$0';
                            if (v >= 1e9) return '$' + (v / 1e9).toFixed(2).replace(/\.?0+$/, '') + 'B';
                            if (v >= 1e6) return '$' + (v / 1e6).toFixed(2).replace(/\.?0+$/, '') + 'M';
                            if (v >= 1e3) return '$' + (v / 1e3).toFixed(2).replace(/\.?0+$/, '') + 'K';
                            return '$' + Math.round(v).toLocaleString('en-US');
                        }

                        function formatDuration(startT, now) {
                            const diff = Math.max(0, Math.floor((now - startT) / 1000));
                            if (diff < 60) return diff + 's';
                            if (diff < 3600) return Math.floor(diff / 60) + 'm ' + (diff % 60) + 's';
                            if (diff < 86400) return Math.floor(diff / 3600) + 'h ' + Math.floor((diff % 3600) / 60) + 'm';
                            return Math.floor(diff / 86400) + 'd ' + Math.floor((diff % 86400) / 3600) + 'h';
                        }

                        function fastFormatPrice(p) {
                            if (p >= 1000) return p.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
                            return p >= 1 ? p.toFixed(2) : p.toFixed(4);
                        }

                        let markPrice = null;
                        const bdiv = document.querySelector('.lo-bt-body tr.bdiv');
                        if (bdiv) {
                            const m = bdiv.innerText.match(/([\d,]+\.?\d*)/);
                            if (m) markPrice = parseFloat(m[1].replace(/,/g, ''));
                        }

                        // 2. React Fiber Extraction (if not cached in step 0)
                        if (rawOrders.length === 0) {
                            const container = document.querySelector('.lo-bt-body');
                            if (container) {
                                const key = Object.keys(container).find(k => k.startsWith('__reactFiber$'));
                                let fiber = container[key];
                                while (fiber) {
                                    let st = fiber.memoizedState;
                                    while (st) {
                                        const val = st.memoizedState;
                                        if (val && typeof val === 'object' && Array.isArray(val['0']) && val['0'].length > 0) {
                                            if (val['0'][0] && (val['0'][0].usd !== undefined || val['0'][0].initUsd !== undefined)) {
                                                rawOrders = val['0'];
                                                break;
                                            }
                                        }
                                        st = st.next;
                                    }
                                    if (rawOrders.length > 0) break;
                                    fiber = fiber.return;
                                }
                            }
                        }

                        const now = Date.now();
                        let resultOrders = [];
                        if (rawOrders && rawOrders.length > 0) {
                            rawOrders.sort((a, b) => b.price - a.price);
                            for (const o of rawOrders) {
                                const venue = (exMap[o.ex] || o.ex.replace(/-/g, ' ').toUpperCase()) + ' ' + (o.side === 'ask' ? 'Ask' : 'Bid');
                                const fromPct = markPrice ? ((o.price - markPrice) / markPrice * 100) : 0;
                                resultOrders.push({
                                    'Venue/Side': venue,
                                    'Price': fastFormatPrice(o.price),
                                    'From Price': (fromPct >= 0 ? '+' : '') + fromPct.toFixed(2) + '%',
                                    'Initial_USD': formatUsd(o.initUsd),
                                    'Remaining_USD': formatUsd(o.usd),
                                    'Filled_USD': formatUsd(o.filledUsd),
                                    'Duration': formatDuration(o.startT, now),
                                    'Status': (o.filledUsd > 0 || o.fills > 0) ? 'Partially Filled' : 'Open'
                                });
                            }
                        }

                        // 3. Robust DOM Fallback if React Fiber yields 0 rows
                        if (resultOrders.length === 0) {
                            const trs = document.querySelectorAll('.lo-bt-body table tbody tr');
                            for (const tr of trs) {
                                if (tr.classList.contains('bdiv')) continue;
                                const tds = Array.from(tr.querySelectorAll('td')).map(td => td.innerText.trim().replace(/\n/g, ' '));
                                if (tds.length >= 8 && tds[0]) {
                                    const venue = tds[0].replace(/[★☆]/g, '').trim();
                                    const fromStr = tds[2] && tds[2].includes('%') ? tds[2] : (markPrice ? (((parseFloat(tds[1].replace(/,/g, '')) - markPrice) / markPrice * 100).toFixed(2) + '%') : '+0.00%');
                                    resultOrders.push({
                                        'Venue/Side': venue,
                                        'Price': tds[1],
                                        'From Price': fromStr,
                                        'Initial_USD': tds[3],
                                        'Remaining_USD': tds[4],
                                        'Filled_USD': tds[5],
                                        'Duration': tds.length > 8 ? tds[7] : tds[6],
                                        'Status': tds.length > 8 ? tds[8] : tds[7]
                                    });
                                }
                            }
                        }

                        const isRateLimited = document.body.innerText.includes('Large-order data failed to load');
                        return { markPrice: markPrice || 0.0, total: resultOrders.length, orders: resultOrders, isRateLimited };
                    })()

(() => {
    if (window.__cg_term) return true;
    const nextEl = document.getElementById('__next');
    if (!nextEl) return false;
    const containerKey = Object.keys(nextEl).find(k => k.startsWith('__reactContainer$'));
    if (!containerKey) return false;
    const rootFiber = nextEl[containerKey];

    let term = null;
    function findTerm(fiber, depth = 0) {
        if (!fiber || depth > 80 || term) return;
        try {
            if (fiber.memoizedProps && fiber.memoizedProps.value && fiber.memoizedProps.value.term) {
                term = fiber.memoizedProps.value.term;
                return;
            }
        } catch(e) {}
        findTerm(fiber.child, depth + 1);
        findTerm(fiber.sibling, depth);
    }
    findTerm(rootFiber);
    if (term) {
        window.__cg_term = term;
        return true;
    }
    return false;
})()

(() => {
    const term = window.__cg_term;
    if (!term || !term.pairs) return ['BTC', 'ETH', 'DOGE', 'ADA', 'XRP', 'LTC', 'LINK'];
    const pairs = term.pairs();
    const aggPerp = pairs.filter(p => p.m && p.m.id === 'agg-perp').map(p => p.s);
    return [...new Set(aggPerp)];
})()

(async (targetSymbol) => {
    const term = window.__cg_term;
    if (!term) return { error: 'CoinGlass terminal window.__cg_term is not hooked' };

    const sym = targetSymbol || 'BTC';
    if (term.prefs.sym !== sym) {
        term.pickPair(sym, 'agg-perp');
        for (let i = 0; i < 25; i++) {
            if (term.prefs.sym === sym && !term.D.loading && term.D.T && term.D.T.length > 0) break;
            await new Promise(r => setTimeout(r, 100));
        }
    }

    // Hard assert Row Size = Auto
    if (term.prefs.tick !== 'auto' && typeof term.setTick === 'function') {
        term.setTick('auto');
    }
    if (term.prefs.tick !== 'auto') {
        return { error: 'Invariant failure: term.prefs.tick could not be set to auto' };
    }

    const results = {
        symbol: sym,
        market: term.prefs.mkt || 'agg-perp',
        sets: []
    };

    function computeAna(D, idx) {
        const cached = term.cache?.ana?.get(idx);
        if (cached && cached.mx !== undefined && cached.mn !== undefined) {
            return cached;
        }
        const i = D.F ? D.F[idx] : null;
        if (!i || !i.b) return { mx: 0, mn: 0 };

        let a = D.obs ? D.obs.get(D.T[idx]) : null;
        let r = 0, n = 0;
        if (a && a.full) {
            r = a.mn;
            n = a.mx;
        } else {
            let e = i.b.length, l = i.lo, o_tick = i.tick;
            if (!o_tick || isNaN(o_tick) || isNaN(l)) return { mx: 0, mn: 0 };
            let h = val => Math.max(0, Math.min(Math.floor((val - l) / o_tick + 1e-9), e - 1));
            let d = h(D.O[idx]), c = h(D.H[idx]), p = h(D.L[idx]), u = h(D.C[idx]);
            if (isNaN(d) || isNaN(c) || isNaN(p) || isNaN(u)) return { mx: 0, mn: 0 };
            let f = D.C[idx] >= D.O[idx] ? [[d, p], [p, c], [c, u]] : [[d, c], [c, p], [p, u]];
            let g = new Uint16Array(e), m = [];
            for (let [e1, t1] of f) {
                let step = e1 <= t1 ? 1 : -1;
                for (let j = e1; m.push(j), g[j]++, j !== t1; j += step);
            }
            for (let j = 0; j < e; j++) {
                if (!g[j] && (i.b[j] || i.s[j])) {
                    m.push(j);
                    g[j] = 1;
                }
            }
            let b = 0;
            for (let j of m) {
                b += (i.b[j] - i.s[j]) / g[j];
                if (b < r) r = b;
                if (b > n) n = b;
            }
            if (a && !a.full) {
                r = Math.min(r, a.mn);
                n = Math.max(n, a.mx);
            }
        }
        return { mx: n, mn: r };
    }

    const barModes = ['time', 'vol', 'range'];

    for (const btType of barModes) {
        if (term.prefs.bt !== btType) {
            term.setBt(btType);
        }
        if (term.prefs.tick !== 'auto' && typeof term.setTick === 'function') {
            term.setTick('auto');
        }

        // Reactive micro-polling instead of static sleeps
        for (let w = 0; w < 25; w++) {
            if (!term.D.loading && term.D.T && term.D.T.length > 0) break;
            await new Promise(r => setTimeout(r, 40));
        }

        const D = term.D;
        if (!D || !D.T || D.T.length === 0) continue;

        // Dynamic query of sigSets AFTER switching bar modes so volume & range signals populate
        const currentSigSets = term.sigSets ? term.sigSets() : [];
        const matchingSet = currentSigSets.find(s => s.bt === btType);
        let rawLabel = matchingSet ? matchingSet.label : btType;
        if (btType === 'time' && term.prefs.itv) {
            rawLabel = term.prefs.itv;
        }

        const signals = [];
        const sigMap = {};

        if (matchingSet && matchingSet.sigs) {
            const sigX = matchingSet.X || D;
            for (const s of matchingSet.sigs) {
                const timeMs = sigX.T ? sigX.T[s.i] : null;
                if (!timeMs) continue;
                const text = (term.sigText ? term.sigText(s, sigX) : null) || ['', ''];
                const sigName = term.sigName ? term.sigName(s) : (s.t || 'Signal');
                const side = (s.side === 'buy' || s.side === 'Bullish') ? 'Bullish' : 'Bearish';
                const title = text[0] || '';
                const desc = text[1] || '';
                const priceSuffix = s.p ? (' · ' + s.p) : '';

                signals.push({
                    time_ms: timeMs,
                    sig_code: s.t || '',
                    sig_name: sigName,
                    side: side,
                    price: s.p || 0.0,
                    title: title,
                    description: desc
                });

                const fullSigStr = title ? `${sigName} (${side}): ${title} - ${desc}${priceSuffix}` : `${sigName} (${side})${desc ? ' - ' + desc : ''}${priceSuffix}`;
                if (!sigMap[timeMs]) {
                    sigMap[timeMs] = [];
                }
                sigMap[timeMs].push(fullSigStr);
            }
        }

        const bars = [];
        const n = D.T.length;

        const deltas = [];
        const clusterMetrics = [];
        for (let i = 0; i < n; i++) {
            const F = D.F ? D.F[i] : null;
            let buyVol = 0.0, sellVol = 0.0, buyCnt = 0, sellCnt = 0, sumPV = 0.0;

            if (F && F.b && F.s) {
                const len = Math.min(F.b.length, F.s.length);
                for (let j = 0; j < len; j++) {
                    const b = F.b[j] || 0.0;
                    const s = F.s[j] || 0.0;
                    const bc = (F.bc && F.bc[j]) || 0;
                    const sc = (F.sc && F.sc[j]) || 0;
                    // Midpoint VWAP: adds +0.5 * tick to eliminate -0.5*tick downward bias
                    const p = (F.lo !== undefined && F.tick) ? (F.lo + (j + 0.5) * F.tick) : D.C[i];
                    buyVol += b;
                    sellVol += s;
                    buyCnt += bc;
                    sellCnt += sc;
                    sumPV += p * (b + s);
                }
            }

            const totalVol = buyVol + sellVol;
            const delta = buyVol - sellVol;
            deltas.push(delta);
            clusterMetrics.push({
                totalVol: totalVol,
                buyVol: buyVol,
                sellVol: sellVol,
                delta: delta,
                vwap: totalVol > 0 ? (sumPV / totalVol) : ((D.H[i] + D.L[i] + D.C[i]) / 3.0),
                trades: buyCnt + sellCnt
            });
        }

        // True continuous cumulative delta (CVD) eliminating viewport step jumps
        let runningCVD = 0.0;
        const continuousCVDs = [];
        for (let i = 0; i < n; i++) {
            runningCVD += deltas[i];
            continuousCVDs.push(runningCVD);
        }

        for (let i = 0; i < n; i++) {
            const t = D.T[i];
            const o = D.O[i];
            const h = D.H[i];
            const l = D.L[i];
            const c = D.C[i];
            const m = clusterMetrics[i];
            const ana = computeAna(D, i);

            // Pure UTC ISO timestamp formatting (eliminating 5.5h local time shift)
            const d = new Date(t);
            const pad = num => String(num).padStart(2, '0');
            const timeUtc = d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()) + ' ' +
                            pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes()) + ':' + pad(d.getUTCSeconds());

            const candleSig = sigMap[t] ? sigMap[t].join(' | ') : '';

            bars.push({
                time_ms: t,
                time_utc: timeUtc,
                open: o,
                high: h,
                low: l,
                close: c,
                volume: m.totalVol,
                buy_volume: m.buyVol,
                sell_volume: m.sellVol,
                delta: m.delta,
                cvd: continuousCVDs[i],
                vwap: m.vwap,
                max_delta_level: ana.mx,
                min_delta_level: ana.mn,
                trades: m.trades,
                signal: candleSig
            });
        }

        results.sets.push({
            bar_type: btType,
            label: rawLabel,
            bars: bars,
            signals: signals
        });
    }

    return results;
})

(async () => {
    const horizons = [
        { label: '3D · 1m', key: '3D' },
        { label: '7D · 3m', key: '7D' },
        { label: '30D · 15m', key: '30D' }
    ];

    const allData = {};
    let isRateLimited = false;

    for (const h of horizons) {
        // 1. Switch horizon tab
        const tfBtn = Array.from(document.querySelectorAll('*')).find(el => el.children.length === 0 && el.innerText && el.innerText.trim() === h.label);
        if (tfBtn) {
            tfBtn.click();
            await new Promise(r => setTimeout(r, 600));
        }

        // 2. Ensure ±4% tab is selected for Key liquidation levels
        const pctBtn = Array.from(document.querySelectorAll('.tab-inner-label, button, div, span, *')).find(el => (el.children.length === 0 || el.classList.contains('tab-inner-label')) && el.innerText && el.innerText.trim() === '±4%');
        if (pctBtn) {
            pctBtn.click();
            await new Promise(r => setTimeout(r, 400));
        }

        // 3. Active Hydration Polling: Wait for Loading... to clear
        const t0 = Date.now();
        while (Date.now() - t0 < 6000) {
            if (!document.body.innerText.includes('Loading…')) break;
            await new Promise(r => setTimeout(r, 200));
        }

        if (document.body.innerText.includes('failed to load') || document.body.innerText.includes('Too Many Requests')) {
            isRateLimited = true;
        }

        // A. Key Liquidation Levels (Within ±4%)
        const keyLevels = [];
        const trs = Array.from(document.querySelectorAll('tbody tr'));
        for (const tr of trs) {
            const tds = Array.from(tr.querySelectorAll('td')).map(td => td.innerText.trim());
            if (tds.length >= 5 && (tds[0].toLowerCase().includes('short') || tds[0].toLowerCase().includes('long'))) {
                const side = tds[0].toLowerCase().includes('short') ? 'Short' : 'Long';
                const pVal = parseFloat(tds[1].replace(/[$,]/g, '')) || 0.0;
                const dVal = tds[2].replace(/[−–—]/g, '-').trim();
                const lev = tds[3].trim();
                const strVal = parseFloat(tds[4].replace(/,/g, '')) || 0.0;
                if (!isNaN(pVal) && pVal > 0) {
                    keyLevels.push({
                        Side: side,
                        Price: pVal,
                        Distance: dVal,
                        Leverage: lev,
                        Strength: strVal
                    });
                }
            }
        }

        const fullText = document.body.innerText;

        // B. Strength By Distance
        const sbdList = [];
        const sbdMatch = fullText.match(/Strength by distance[\s\S]*?Total strength in each band[^\n]*\n([\s\S]*?)(?=By leverage tier|Magnet zones|Near-field balance|$)/i);
        if (sbdMatch) {
            const block = sbdMatch[1];
            const bandRegex = /(\d+[\–\-]\d+%)\s*(?:\n|\s)\s*([\d,]+)\s*(?:\n|\s)\s*·\s*(?:\n|\s)\s*([\d,]+)/g;
            let m;
            while ((m = bandRegex.exec(block)) !== null) {
                const band = m[1].replace('–', '-');
                const sStr = parseFloat(m[2].replace(/,/g, '')) || 0.0;
                const lStr = parseFloat(m[3].replace(/,/g, '')) || 0.0;
                const tot = sStr + lStr;
                sbdList.push({
                    Band: band,
                    Short_Strength: sStr,
                    Long_Strength: lStr,
                    Total_Strength: tot,
                    Short_Share_Pct: tot > 0 ? ((sStr / tot) * 100).toFixed(2) + '%' : '0.00%',
                    Long_Share_Pct: tot > 0 ? ((lStr / tot) * 100).toFixed(2) + '%' : '0.00%'
                });
            }
        }

        // C. By Leverage Tier (OpenLevelLeverageStrength)
        const levList = [];
        const levMatch = fullText.match(/By leverage tier[\s\S]*?Open-level strength per leverage tier[^\n]*\n([\s\S]*?)(?=Strength by distance|Magnet zones|Near-field balance|$)/i);
        if (levMatch) {
            const block = levMatch[1];
            const tierRegex = /(High leverage|Mid leverage|Low leverage)\s*(?:\n|\s)\s*([\d,]+)\s*(?:\n|\s)\s*·\s*(?:\n|\s)\s*([\d,]+)/g;
            let m;
            while ((m = tierRegex.exec(block)) !== null) {
                const tier = m[1];
                const sStr = parseFloat(m[2].replace(/,/g, '')) || 0.0;
                const lStr = parseFloat(m[3].replace(/,/g, '')) || 0.0;
                const tot = sStr + lStr;
                levList.push({
                    Tier: tier,
                    Short_Strength: sStr,
                    Long_Strength: lStr,
                    Total_Strength: tot,
                    Short_Share_Pct: tot > 0 ? ((sStr / tot) * 100).toFixed(2) + '%' : '0.00%',
                    Long_Share_Pct: tot > 0 ? ((lStr / tot) * 100).toFixed(2) + '%' : '0.00%'
                });
            }
        }

        // D. Magnet Zones
        const magnetList = [];
        const parseSide = (block, sideName) => {
            const items = [];
            const lines = block.split('\n').map(l => l.trim()).filter(Boolean);
            let cur = null;
            for (let idx = 0; idx < lines.length; idx++) {
                const l = lines[idx];
                const rankM = l.match(/^([123])$/);
                if (rankM) {
                    if (cur) items.push(cur);
                    cur = { Rank: parseInt(rankM[1]), Side: sideName };
                    continue;
                }
                if (cur) {
                    if (!cur.Price_Range && l.includes('−') || (l.includes('-') && !l.includes('%'))) {
                        const parts = l.split(/[−-]/).map(p => parseFloat(p.replace(/[$,]/g, ''))).filter(p => !isNaN(p));
                        cur.Price_Range = l;
                        cur.Price_Low = parts[0] || 0.0;
                        cur.Price_High = parts[1] || parts[0] || 0.0;
                        continue;
                    }
                    if (cur.Price_Range && !cur.Strength && /^\d+$/.test(l.replace(/,/g, ''))) {
                        cur.Strength = parseFloat(l.replace(/,/g, '')) || 0.0;
                        continue;
                    }
                    if (l.startsWith('+') || l.startsWith('-') || l.startsWith('−')) {
                        cur.Distance = l.replace(/[−–]/g, '-');
                        continue;
                    }
                    if (l.toLowerCase().includes('width')) {
                        cur.Band_Width = l.replace(/width\s*/i, '').trim();
                        continue;
                    }
                }
                if (l.toLowerCase().includes('no significant zone')) {
                    items.push({
                        Rank: 1,
                        Side: sideName,
                        Price_Range: 'None',
                        Price_Low: 0.0,
                        Price_High: 0.0,
                        Distance: '0.00%',
                        Strength: 0.0,
                        Band_Width: '0.00%',
                        Status: 'No significant zone on this side'
                    });
                }
            }
            if (cur) items.push(cur);
            return items.map(it => ({
                Side: it.Side,
                Rank: it.Rank,
